import{Ct as e,Q as t,rt as n,t as r,tt as i}from"./chunks/framework.D_6UCjGC.js";var a=JSON.parse(`{"title":"Document","description":"","frontmatter":{"title":"Document","order":2},"headers":[],"relativePath":"services/document/index.md","filePath":"services/document/index.md"}`),o={name:`services/document/index.md`};function s(r,a,o,s,c,l){return e(),i(`div`,{"data-pagefind-body":!0,"data-pagefind-meta":`date:1795284828000`},[...a[0]||=[n(`<h1 id="document-service" tabindex="-1">Document Service <a class="header-anchor" href="#document-service" aria-label="Permalink to “Document Service”">​</a></h1><p>NestJS service holding the collaborative (Yjs / Blocknote) content of notes and serving the realtime websocket. Note content is committed back to the Note service through events.</p><ul><li><a href="./domain.html">Domain</a>: class diagrams</li><li><a href="./data.html">Data</a>: database schema</li><li><a href="./flows.html">Flows</a>: collaboration, commits, and deletion</li></ul><h2 id="use-cases" tabindex="-1">Use cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to “Use cases”">​</a></h2><table tabindex="0"><thead><tr><th>Use case</th><th>Behavior</th></tr></thead><tbody><tr><td>Collaborate on a note</td><td>Connect using a JWT and note read permission; users without write permission and users viewing trashed notes connect read-only. Edits are synchronized as Yjs updates and stored with a debounce.</td></tr><tr><td>Commit content</td><td>A writer can commit manually. Eligible plans also commit after stores or sweep idle modified documents. A commit creates a revision and publishes content, tags, and outgoing links for downstream consumers.</td></tr><tr><td>Manage revision history</td><td>List revisions with pagination and an optional trigger filter, read a snapshot with content, rename it, or hard-delete it. A retention job purges old revisions according to the plan while keeping the latest.</td></tr><tr><td>Upload an attachment</td><td>A writer requests a presigned upload URL and public URL for an attachment associated with the document.</td></tr><tr><td>React to access or note changes</td><td>Workspace role and membership events update or close live connections. A note deletion closes connections and removes its document and revisions.</td></tr></tbody></table><p>HTTP authentication trusts gateway-forwarded user headers; the WebSocket validates its own JWT. The revision handlers currently do not perform a per-document authorization check; they should not be assumed to enforce the same permissions as commit or attachment upload.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h2>`,7),t(`figure`,{class:`vpd-diagram vpd-diagram--d2`,onclick:`
        const figure = this;
        const isFullscreen = figure.classList.contains('vpd-diagram--fullscreen');

        document.querySelectorAll('.vpd-diagram').forEach(diagram => {
          diagram.classList.remove('vpd-diagram--fullscreen');
        });

        if (!isFullscreen) {
          figure.classList.add('vpd-diagram--fullscreen');
        }
      `},[t(`img`,{src:`/notopia/pr/352/diagrams/d2-architecture-document-diagram-eb54c7ed0ed15aaee0abaf6210ab9141.svg`,alt:`d2 Diagram`,class:`vpd-diagram-image`})],-1)]])}var c=r(o,[[`render`,s]]);export{a as __pageData,c as default};